style.css:
@-moz-document domain("roblox.com") {
body::before {
    content: "";
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: url("https://i.imgur.com/sT1UjeI.jpeg") center center / cover no-repeat;
    z-index: -1;
    opacity: 0.4;
  }
  body, html {
    background: transparent !important;
    color: #fff !important;
  }
  .container-main, .content, .navbar, .footer {
    background: rgba(0,0,0,0.6) !important;
  }
}
